starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

starter.variables.tf:
variable "container_name" {
  description = "Input variable container_name."
  type        = string
  default     = "web"
}

variable "image" {
  description = "Input variable image."
  type        = string
  default     = "nginx:alpine"
}

variable "host_port" {
  description = "Input variable host_port."
  type        = number
  default     = 8080
}

starter.main.tf:
provider "docker" {
  host = var.docker_host
}

resource "docker_container" "this" {
  # TODO - Complete the docker_container resource.
  # Add the arguments and nested blocks required for docker_container.
}
